P.QAUD = {"seeker":["Apa kaitan bagian firman ini dengan kehidupan saya sekarang?","Saya bukan orang Kristen. Apa arti bagian ini bagi saya?","Apakah Allah itu ada? Apa saja alasan untuk percaya?","Mengapa Alkitab berkata bahwa setiap orang membutuhkan Yesus?","Saya sedang sangat tertekan. Pertolongan praktis apa yang diberikan Alkitab?","Apa arti “dosa” di sini, dan apakah itu berlaku bagi saya?","Orang Kristen berbicara tentang “anugerah”. Apa artinya dengan kata-kata sederhana?","Jika saya ingin tahu lebih banyak, dari mana saya bisa mulai?"],"teen":["Apa kaitan bagian firman ini dengan keseharian saya, yaitu sekolah, teman, dan ponsel?","Seandainya bagian firman ini adalah pesan Allah untuk saya, apa yang akan dikatakan-Nya?","Semua orang melakukannya. Apakah aneh kalau saya tidak ikut? Apa kata Alkitab?","Bisakah kamu menjelaskan bagian firman ini dengan permainan atau film?","Apa hal mengejutkan atau jarang diketahui tentang bagian firman ini?","Stres ujian sangat besar. Kekuatan apa yang diberikan bagian firman ini kepada saya?","Saya tidak bisa mengampuni seseorang. Bagaimana bagian firman ini menolong saya?","Apakah Allah sungguh melihat saya? Apa yang membuat saya layak dikasihi?"],"kid":["Kisah ini tentang apa? Ceritakan kepadaku.","Apa yang dilakukan Allah dalam kisah ini?","Apakah Yesus mengasihiku? Bagaimana aku tahu?","Siapa yang paling berani dalam kisah ini? Mengapa?","Bagaimana aku bisa menjadi seperti orang-orang dalam kisah ini?","Ajari aku satu ayat pendek yang bisa kuingat.","Aku bertengkar dengan sahabatku. Apa yang akan Yesus lakukan?","Bisakah kamu mengajariku doa pendek?"]};
P.AUD2 = {"elder":{"q":["Dengan kata-kata yang paling sederhana, apa yang dikatakan bagian firman ini?","Penghiburan apa yang diberikan bagian firman ini bagi mereka yang sudah lanjut usia?","Tubuh saya kian lemah. Bagaimana Allah menjaga saya?","Saya sering merasa kesepian. Apa yang diberikan bagian firman ini kepada saya?","Bagaimana saya dapat mewariskan iman kepada anak dan cucu saya?","Ada hal-hal yang tidak dapat saya lepaskan. Bagaimana bagian firman ini mengajar saya untuk menyerahkannya?","Saya sudah tua. Apa yang masih bisa saya lakukan bagi Allah?","Tolong tuliskan doa singkat yang dapat saya bacakan kepada Tuhan."],"fu":["Kesehatan","Kesepian","Keluarga","Menyerahkan","Harapan","Doa"],"rw":["Anda telah menamatkan seluruh kitab {nm}!","Hari demi hari Anda sampai sejauh ini. Allah mengingat kesetiaan ini, dan ini menjadi teladan bagi kami yang lebih muda."],"res":["Tidak apa-apa, pelan-pelan saja. Membacanya sekali lagi akan membuatnya lebih jelas.","Bagus sekali! Anda mengingat banyak hal dari pasal ini.","Luar biasa! Firman itu hidup dalam hati Anda."]},"single_parent":{"q":["Penghiburan apa yang diberikan bagian firman ini kepada saya yang memikul keluarga seorang diri?","Saya sangat lelah dan merasa berutang lebih banyak kepada anak-anak saya. Bagaimana Allah memandang saya?","Bagaimana Allah memperhatikan anak yatim dan janda, dan apa artinya bagi saya?","Keuangan saya sangat sulit. Apa yang diberikan bagian firman ini kepada saya?","Anak saya membantah dan emosinya meledak-ledak. Apa yang harus saya lakukan?","Saya tidak tahu bagaimana berbicara kepada anak saya tentang ayah (atau ibunya) yang tidak ada di sisinya.","Saya sungguh kesepian. Bagaimana saya dapat meminta bantuan kepada gereja atau saudara seiman?","Tolong tuliskan doa singkat yang dapat saya doakan dalam lima menit."],"fu":["Lelah","Anak","Uang","Pertolongan","Harapan","Doa"],"rw":["Anda telah menamatkan seluruh kitab {nm}!","Tetap membaca Alkitab sambil memikul keluarga seorang diri bukanlah hal mudah. Allah melihat setiap langkah Anda, dan Dia menyertai Anda."],"res":["Tidak apa-apa, Anda sudah berusaha keras. Bacalah lagi saat ada waktu.","Bagus! Anda mengingat begitu banyak di tengah hari-hari yang sibuk.","Luar biasa! Firman itu menopang Anda."]},"single":{"q":["Sebagai seorang lajang, apa yang dikatakan bagian firman ini kepada saya?","Saya merasa kesepian. Apa yang diberikan bagian firman ini kepada saya?","Siapakah saya di dalam Kristus, dan apa nilai saya?","Bagaimana saya percaya kepada Allah selama menanti?","Hikmat apa yang diberikan Alkitab tentang hubungan antarmanusia?","Bagaimana waktu dan tenaga saya sebagai orang lajang dapat dipakai bagi Allah?","Bagaimana saya membangun hubungan yang baik di gereja dan dengan sahabat-sahabat?","Tolong tuliskan doa singkat bagi seorang lajang."],"fu":["Kesepian","Jati diri","Menanti","Hubungan","Panggilan","Doa"],"rw":["Anda telah menamatkan seluruh kitab {nm}!","Anda terus melangkah seorang diri, dan di hadapan Allah hari-hari Anda utuh dan dikasihi."],"res":["Tidak apa-apa, pelan-pelan saja. Membacanya sekali lagi akan membuatnya lebih jelas.","Bagus! Anda sudah menangkap inti pasal ini.","Luar biasa! Anda tekun, dan firman itu berakar dalam diri Anda."]},"parent":{"q":["Apa yang diingatkan bagian firman ini kepada saya sebagai orangtua?","Anak saya tidak mau mendengar dan emosinya meledak-ledak. Bagaimana saya harus menanggapinya?","Bagaimana menyeimbangkan disiplin dan kasih karunia?","Bagaimana berbicara dengan baik kepada seorang remaja?","Saya sering kehilangan kesabaran terhadap anak saya dan merasa bersalah sesudahnya. Lalu bagaimana?","Bagaimana saya menuntun anak saya mengenal Allah, bukan sekadar pergi ke gereja?","Saya dan pasangan tidak sepakat dalam cara mendidik anak. Apa kata bagian firman ini?","Tolong tuliskan doa berkat singkat untuk anak saya."],"fu":["Berbicara","Disiplin","Rasa bersalah","Pasangan","Iman","Doa"],"rw":["Anda telah menamatkan seluruh kitab {nm}!","Membaca Alkitab hari demi hari di tengah kesibukan membesarkan anak, itulah teladan terbaik yang dapat Anda berikan kepada mereka."],"res":["Tidak apa-apa, pelan-pelan saja. Bacalah lagi saat ada waktu.","Bagus! Anda sudah menangkap inti pasal ini.","Luar biasa! Firman itu berakar dalam rumah tangga Anda."]},"couple":{"q":["Apa yang dikatakan bagian firman ini kepada kami sebagai suami istri?","Setelah bertengkar, kami saling mendiamkan. Bagaimana salah satu dari kami dapat mengulurkan tangan lebih dahulu?","Bagaimana saya dapat mengungkapkan isi hati saya agar pasangan saya dapat mendengarnya?","Pasangan saya telah menyakiti saya. Apakah saya sungguh harus mengampuni?","Kami berbeda pendapat soal uang dan pekerjaan rumah. Apa yang harus kami lakukan?","Bagaimana kami dapat berdoa dan mendekat kepada Allah bersama-sama?","Kami menjadi renggang karena kesibukan. Bagaimana kami dapat terhubung kembali?","Tolong tuliskan doa berkat singkat bagi pernikahan kami."],"fu":["Berbicara","Mengampuni","Keakraban","Sehati","Bersama","Doa"],"rw":["Kalian berdua telah menamatkan seluruh kitab {nm}!","Pasangan yang bersama-sama mendekat kepada firman Allah berdiri di atas dasar yang kokoh."],"res":["Tidak apa-apa, pelan-pelan saja. Bacalah lagi bersama di suatu malam.","Bagus! Kalian sudah menangkap inti pasal ini.","Luar biasa! Firman Allah berakar dalam pernikahan kalian."]},"pastor":{"q":["Apa yang dikatakan bagian firman ini kepada saya dalam pelayanan?","Bantu saya menemukan kerangka khotbah dan pintu masuk untuk bagian firman ini.","Saya kelelahan dan nyaris terbakar habis. Bagaimana bagian firman ini menghibur saya?","Bagaimana saya menghadapi kritik dan kesalahpahaman di gereja?","Apa yang dikatakan bagian firman ini tentang memimpin tim agar tetap bersatu?","Bagaimana saya menjaga hubungan pribadi saya dengan Allah di tengah pelayanan yang sibuk?","Bagaimana saya menggembalakan mereka yang lemah, terluka, dan yang telah pergi?","Tolong tuliskan doa syafaat singkat bagi gereja dan rekan-rekan sepelayanan saya."],"fu":["Khotbah","Penggembalaan","Tim","Istirahat","Peperangan rohani","Syafaat"],"rw":["Anda telah menamatkan seluruh kitab {nm}!","Tetap dekat dengan firman Allah di tengah pelayanan yang sibuk adalah akar terdalam dari penggembalaan."],"res":["Tidak apa-apa, pelan-pelan saja. Bacalah lagi saat ada waktu.","Bagus! Anda sudah menangkap inti pasal ini.","Luar biasa! Firman Allah memberi makan gembala lebih dahulu, lalu mengalir kepada kawanan domba."]}};
